//! Conformance DIFFERENTIAL (P4 strangler-fig) — pins `casl_core::wellformed_core` to the authoritative
//! verdicts on a shared corpus. The corpus (`tests/corpus.json`) is generated by
//! `src/casl/tcb_corpus.py::write_rust_corpus` from the SAME bounded enumeration that feeds the OCaml
//! driver; each verdict is `tcb_bridge.projectable`, itself pinned to the F*-extracted kernel by the TCB
//! bridge. So this test makes Rust ↔ Python(↔F*) agree on every protocol — the safety net that lets the
//! Rust core eventually become authoritative (never two unpinned impls). Regenerate:
//!   PYTHONPATH=src python -m casl.tcb_corpus
use casl_core::{wellformed_core, Branch, Gtyp};
use serde_json::Value;

fn s(v: &Value, k: &str) -> String {
    v[k].as_str().expect("string field").to_string()
}

fn parse(v: &Value) -> Gtyp {
    match v["t"].as_str().expect("tag") {
        "end" => Gtyp::End,
        "var" => Gtyp::Var(s(v, "v")),
        "rec" => Gtyp::Rec {
            var: s(v, "v"),
            body: Box::new(parse(&v["g"])),
            measure: None,
            max_iters: None,
        },
        "msg" => Gtyp::Comm {
            sender: s(v, "s"),
            receiver: s(v, "r"),
            label: s(v, "l"),
            fields: vec![],
            cont: Box::new(parse(&v["k"])),
            contract: None,
            uses_capability: None,
            from_oracle: false,
            on_crash: None,
        },
        "ch" => {
            let branches = v["opts"]
                .as_array()
                .expect("opts array")
                .iter()
                .map(|o| {
                    let a = o.as_array().expect("[label, gtyp]");
                    Branch {
                        label: a[0].as_str().expect("label").to_string(),
                        fields: vec![],
                        cont: parse(&a[1]),
                        contract: None,
                    }
                })
                .collect();
            Gtyp::Choice {
                sender: s(v, "s"),
                receiver: s(v, "r"),
                branches,
            }
        }
        other => panic!("unknown gtyp tag {other:?}"),
    }
}

#[test]
fn casl_core_wellformed_matches_authoritative_corpus() {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/corpus.json");
    let data = std::fs::read_to_string(path)
        .expect("tests/corpus.json present (regen: PYTHONPATH=src python -m casl.tcb_corpus)");
    let corpus: Value = serde_json::from_str(&data).expect("valid JSON corpus");
    let arr = corpus.as_array().expect("corpus is an array");
    assert!(
        arr.len() >= 100,
        "corpus should be substantial, got {}",
        arr.len()
    );

    let mut checked = 0usize;
    let mut disagree: Vec<String> = Vec::new();
    for item in arr {
        let g = parse(&item["g"]);
        let expected = item["wf"].as_bool().expect("wf bool");
        let got = wellformed_core(&g);
        if got != expected {
            disagree.push(format!(
                "{}: casl-core={got} authoritative={expected}",
                item["name"].as_str().unwrap_or("?")
            ));
        }
        checked += 1;
    }
    assert!(
        disagree.is_empty(),
        "{}/{} protocol(s) diverge from the authoritative (F*-pinned) verdict: {:?}",
        disagree.len(),
        checked,
        &disagree[..disagree.len().min(10)]
    );
    eprintln!(
        "differential: casl-core agrees with the authoritative verdict on all {checked} protocols"
    );
}
